@BoxBIF( description = "Work with spreadsheet files" )
public class Spreadsheet extends BIF {

	/**
	 * Constructor
	 */
	public Spreadsheet() {
		super();
		declaredArguments = new Argument[] {
		    new Argument( false, Argument.STRING, Key.path ),
		    new Argument( false, Argument.STRING, KeyDictionary.SHEETNAME ),
		    new Argument( false, Argument.BOOLEAN, KeyDictionary.XMLFORMAT, true ),
		    new Argument( false, Argument.STRING, KeyDictionary.PASSWORD ),
		};
	}

	/**
	 * Get a fluent SpreadsheetFile object that can be used to read or write properties to a loaded spreadsheet file or a new one.
	 * If the path is not specified, it will return a blank spreadsheet file object you can use to write properties to a new file.
	 * If the path is specified and valid, it will load the spreadsheet file from that path.
	 * If the path is specified but not valid, it will set the path for a new file to be created later.
	 *
	 * @param context   The context in which the BIF is being invoked.
	 * @param arguments Argument scope for the BIF.
	 *
	 * @argument.path The path to the spreadsheet file to load or the path where the spreadsheet file will be stored at
	 *
	 * @argument.sheetname The name of the sheet to work with (optional). Default is "Sheet1".
	 *
	 * @argument.xmlformat Whether the spreadsheet should use XML format (.xlsx). Default is true.
	 *
	 * @return A fluent SpreadsheetFile object that can be used to read or write properties.

